import { ScrollView, Text } from 'react-native';

export function Settings({ options }) {
  return (
    <ScrollView>
      {options.map((option) => (
        <Text key={option.id}>{option.label}</Text>
      ))}
    </ScrollView>
  );
}

import { memo, useCallback } from 'react';
import { FlatList, Text, View } from 'react-native';

const Row = memo(function Row({ title }) {
  return (
    <View style={{ height: 64, justifyContent: 'center' }}>
      <Text>{title}</Text>
    </View>
  );
});

export function OrdersList({ orders, refreshing, onRefresh, onLoadMore }) {
  const renderItem = useCallback(({ item }) => <Row title={item.title} />, []);

  return (
    <FlatList
      data={orders}
      renderItem={renderItem}
      keyExtractor={(item) => String(item.id)}
      refreshing={refreshing}
      onRefresh={onRefresh}
      onEndReached={onLoadMore}
      onEndReachedThreshold={0.5}
      ListEmptyComponent={<Text>No orders yet</Text>}
    />
  );
}

const ROW_HEIGHT = 64;

const getItemLayout = (data, index) => ({
  length: ROW_HEIGHT,
  offset: ROW_HEIGHT * index,
  index,
});

<FlatList data={orders} renderItem={renderItem} getItemLayout={getItemLayout} />

import { FlashList } from '@shopify/flash-list';

<FlashList
  data={orders}
  renderItem={renderItem}
  keyExtractor={(item) => String(item.id)}
/>
